import json, glob
want={f'MAT-LIT-{i:03d}' for i in range(90,116)}
mats={}
for p in ['state/materials.jsonl']+glob.glob('state/materials.d/*.jsonl'):
    for line in open(p, encoding='utf-8'):
        if line.strip():
            r=json.loads(line)
            if r.get('material_id') in want:
                mats[r['material_id']]=r.get('title')
for i in range(90,116):
    mid=f'MAT-LIT-{i:03d}'
    print(mid, mats.get(mid))
